{
  "appName": "Online Learning Platform",
  "appType": "e-learning",
  "summary": "An online learning platform where instructors publish courses and students enroll, complete lessons, and provide reviews, with a freemium model offering access to paid courses and certificates via a premium subscription.",
  "entities": [
    {
      "name": "course",
      "fields": ["title", "description", "instructorId", "price", "isFree"]
    },
    {
      "name": "lesson",
      "fields": ["title", "videoUrl", "courseId"]
    },
    {
      "name": "enrollment",
      "fields": ["userId", "courseId", "enrollmentDate"]
    },
    {
      "name": "lessonCompletion",
      "fields": ["userId", "lessonId", "completionDate"]
    },
    {
      "name": "review",
      "fields": ["userId", "courseId", "rating", "comment"]
    },
    {
      "name": "subscription",
      "fields": ["userId", "startDate", "endDate", "planType"]
    }
  ],
  "roles": ["instructor", "student", "premium_subscriber"],
  "features": [
    "courseManagement",
    "lessonManagement",
    "studentEnrollment",
    "lessonCompletionTracking",
    "courseReviews",
    "instructorDashboard",
    "paymentProcessing",
    "subscriptionManagement",
    "certificateGeneration"
  ],
  "hasAuth": true,
  "hasPayments": true,
  "ambiguities": [],
  "assumptions": [
    "Users will have distinct roles of 'instructor' and 'student'.",
    "A 'premium subscription' implies a recurring payment model.",
    "Completion certificates are generated upon completion of all lessons in a paid course.",
    "Course ratings are numerical (e.g., 1-5 stars)."
  ],
  "clarifyingQuestions": []
}
